/**
 * The agent catalog (feature-005, Data Model §2.28..§2.30): the public API described for agents,
 * generated by `tools/agent-catalog` from the published types, never typed by hand (REQ-530).
 */

export type Framework = 'react' | 'vue' | 'angular' | 'reflex';
/** The three frameworks with a component layer of their own (no Reflex binding: it wraps React). */
export type AdapterFramework = Exclude<Framework, 'reflex'>;

export type Names = Readonly<Record<Framework, string>>;
export type Imports = Readonly<Record<Framework, string>>;

/** What a chart's rows hold (API delta §3). */
export type DataShape =
  | 'series'
  | 'categories'
  | 'parts'
  | 'matrix'
  | 'hierarchy'
  | 'links'
  | 'points'
  | 'distribution'
  | 'intervals'
  | 'events'
  | 'single'
  | 'field';

/** What the reader is asked to see (API delta §3). */
export type Intent =
  | 'trend'
  | 'compare'
  | 'rank'
  | 'part-to-whole'
  | 'distribution'
  | 'correlation'
  | 'flow'
  | 'hierarchy'
  | 'change'
  | 'uncertainty'
  | 'progress'
  | 'schedule'
  | 'kpi'
  | 'network';

/**
 * The chart families, the slugs of the nine the official site and `reflex-silverpoint-react`
 * already show (Data Model §2.29, fixed at T-227).
 */
export type Family =
  | 'lines'
  | 'bars'
  | 'areas'
  | 'points-grids'
  | 'flows'
  | 'radial'
  | 'distributions-comparisons'
  | 'hierarchies-dimensions'
  | 'fields-networks';

export interface PropEntry {
  /** camelCase, as the types. */
  readonly name: string;
  /** snake_case, from the Reflex catalog; absent when Reflex lacks it. */
  readonly reflex?: string;
  readonly type: string;
  readonly optional: boolean;
  /** From API Spec §5.1, the core's own fallback literal, or the JSDoc. */
  readonly default?: string;
  readonly doc: string;
}

export interface DataField {
  /** What the field means to the chart: `x`, `value`, `source`… */
  readonly role: string;
  /** The accessor prop that names the field (`xKey`, `keys`…). */
  readonly prop: string;
  /** `array` for a field holding a list (a sparkline's points, a heatmap row's values). */
  readonly type: 'string' | 'number' | 'date' | 'array';
  readonly required: boolean;
}

export interface DataSpec {
  readonly shape: DataShape;
  readonly fields: readonly DataField[];
}

export interface ChartEntry {
  readonly slug: string;
  readonly names: Names;
  readonly imports: Imports;
  readonly family: Family;
  readonly summary: string;
  readonly data: DataSpec;
  readonly intents: readonly Intent[];
  /** Own props only; the shared ones are in `common.chart`. */
  readonly props: readonly PropEntry[];
  /** The export holding the demo rows; absent when the chart draws from its props alone. */
  readonly demo?: string;
  /** The demo's accessor props, which name its non-default fields. */
  readonly demoKeys?: Readonly<Record<string, unknown>>;
  /** The demo's first rows: the shape of the data, by example, read through `demoKeys`. */
  readonly demoSample?: readonly unknown[];
  /** `rootId` + `onRootChange` (REQ-439). */
  readonly drillable?: boolean;
  /** Present when the Reflex catalog wraps another silverpoint version (REQ-556). */
  readonly stale?: string;
}

/** How a component's value or open state is bound, per framework. */
export interface Binding {
  readonly value?: Readonly<Record<AdapterFramework, string>>;
  readonly open?: Readonly<Record<AdapterFramework, string>>;
}

export interface ComponentEntry {
  readonly slug: string;
  readonly names: Names;
  readonly imports: Imports;
  readonly family: 'ui' | 'composed' | 'overlay';
  readonly group: string;
  readonly summary: string;
  readonly props: readonly PropEntry[];
  readonly binding?: Binding;
  /** Event names per framework: React handler props, Vue emits, Angular outputs. */
  readonly events: Readonly<Record<AdapterFramework, readonly string[]>>;
  /** Named content per framework: React node props, Vue slots, Angular templates and projections. */
  readonly slots: Readonly<Record<AdapterFramework, readonly string[]>>;
  /** Declared states (Data Model §5). */
  readonly states: readonly string[];
  readonly stale?: string;
}

export interface Diagnostic {
  readonly code: string;
  readonly severity: 'warn' | 'error';
  readonly req: string;
  readonly what: string;
  readonly todo: string;
}

export interface Ground {
  readonly name: string;
  readonly substrates: readonly string[];
  readonly summary: string;
}

export interface AgentCatalog {
  readonly schema: 1;
  /** The library version described (REQ-534). */
  readonly version: string;
  readonly reflex: { readonly version: string; readonly wraps: string; readonly stale: boolean };
  readonly frameworks: readonly Framework[];
  readonly families: readonly { readonly slug: Family; readonly title: string }[];
  readonly common: { readonly chart: readonly PropEntry[]; readonly ui: readonly PropEntry[] };
  readonly charts: readonly ChartEntry[];
  readonly components: readonly ComponentEntry[];
  readonly dashboard: {
    readonly props: readonly PropEntry[];
    readonly layout: readonly PropEntry[];
    readonly cell: readonly PropEntry[];
    readonly names: Names;
    readonly imports: Imports;
  };
  readonly grounds: readonly Ground[];
  readonly palettes: { readonly fields: readonly PropEntry[]; readonly presets: Readonly<Record<string, Readonly<Record<string, string>>>> };
  readonly timeline: { readonly props: readonly PropEntry[]; readonly names: Names; readonly imports: Imports; readonly peer: string };
  readonly diagnostics: readonly Diagnostic[];
  readonly stylesheets: { readonly always: readonly string[]; readonly ui: readonly string[]; readonly timeline: readonly string[] };
}

/** `reflex-catalog.json`, exported by `reflex-silverpoint-react` (Data Model §2.30, DD-049). */
export interface ReflexCatalog {
  readonly schema: 1;
  readonly package: 'reflex-silverpoint-react';
  /** The wheel's version. */
  readonly version: string;
  /** `SILVERPOINT_VERSION`: the silverpoint version that release wraps. */
  readonly wraps: string;
  /** How the file was produced, when not by the package's own export (the interim pin of T-231). */
  readonly derived?: string;
  /** The props every chart and every component share, with their Python names. */
  readonly common?: { readonly chart: readonly ReflexProp[]; readonly ui: readonly ReflexProp[] };
  readonly charts: readonly {
    readonly slug: string;
    readonly builder: string;
    readonly cls: string;
    readonly family: string;
    readonly summary?: string;
    readonly props: readonly ReflexProp[];
  }[];
  readonly components: readonly {
    readonly slug: string;
    readonly builder: string;
    readonly cls: string;
    readonly props: readonly ReflexProp[];
    readonly positional: readonly string[];
    readonly deprecated: Readonly<Record<string, string>>;
  }[];
  readonly helpers: readonly string[];
}

export interface ReflexProp {
  readonly name: string;
  readonly js: string;
  readonly type: string;
}
